"""Standalone interactive HTML search results."""
from html import escape
from pathlib import Path
from urllib.parse import quote

def html_report(query, results, root):
    cards=[]
    for index,result in enumerate(results,1):
        href=Path(root,result['source']).resolve().as_uri()+'#L'+str(result['line'])
        cards.append(f'<li><span>{index:02}</span><div><a href="{escape(href,quote=True)}">{escape(result["source"])}:{result["line"]}</a><p>{escape(result["excerpt"])}</p></div><b>{round(result["score"]*100)}%</b></li>')
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Local Search Kit results</title><style>{STYLE}</style></head><body><a class="skip" href="#results">Skip to results</a><header><strong>LOCAL / SEARCH</strong><span>OFFLINE · KEYWORD INDEX</span></header><main><p class="eyebrow">PRIVATE DOCUMENT DISCOVERY</p><h1>Find the line.<br><em>Keep the source.</em></h1><section class="query"><span>QUERY</span><b>{escape(query)}</b><i>{len(results)} RESULT{'S' if len(results)!=1 else ''}</i></section><ol id="results">{''.join(cards)}</ol><p id="empty" {'hidden' if results else ''}>No matching lines. Try fewer or different words.</p><p class="note">Scores are lexical query-word coverage, not confidence. Links reference local files and may be restricted by browser security settings.</p></main></body></html>'''

STYLE='''*{box-sizing:border-box}:root{color-scheme:dark;--bg:#0a0d0c;--panel:#121917;--line:#293a35;--ink:#f1f5ee;--muted:#95a59f;--green:#85f5ad}body{margin:0;background:radial-gradient(circle at 80% 0,#183629 0,transparent 36%),var(--bg);color:var(--ink);font:15px/1.6 system-ui,sans-serif}header,main{max-width:1180px;margin:auto}header{padding:24px 5vw;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;font:10px ui-monospace,monospace;letter-spacing:2px}header strong,.eyebrow{color:var(--green)}main{padding:60px 5vw 80px}.eyebrow{font:10px ui-monospace,monospace;letter-spacing:3px}h1{font-size:clamp(48px,8vw,92px);line-height:.95;letter-spacing:-.065em;margin:18px 0 46px}h1 em{font-style:normal;color:var(--green)}.query{display:grid;grid-template-columns:90px 1fr auto;gap:20px;align-items:center;padding:18px 20px;background:var(--panel);border:1px solid var(--line);border-radius:12px}.query span,.query i{color:var(--muted);font:10px ui-monospace,monospace;letter-spacing:1px}.query i{font-style:normal}ol{list-style:none;padding:0;margin:18px 0;border:1px solid var(--line);border-radius:12px;overflow:hidden}li{display:grid;grid-template-columns:48px 1fr 60px;gap:18px;padding:20px;background:var(--panel);border-bottom:1px solid var(--line)}li:last-child{border:0}li>span,li>b{color:var(--muted);font:12px ui-monospace,monospace}li>b{color:var(--green);text-align:right}a{color:var(--green);font-weight:700;text-underline-offset:4px;overflow-wrap:anywhere}li p{margin:7px 0 0;color:#c4cfca;overflow-wrap:anywhere}.note,#empty{color:var(--muted)}a:focus-visible{outline:3px solid var(--green);outline-offset:4px}.skip{position:absolute;top:-100px;left:10px;background:var(--green);color:#000;padding:8px}.skip:focus{top:10px}@media(max-width:640px){h1{font-size:48px}.query{grid-template-columns:1fr}.query span{display:none}li{grid-template-columns:32px 1fr}li>b{grid-column:2;text-align:left}}'''
